import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import crypto from 'node:crypto';
import {selectProducts} from '../src/lib/catalog.mjs';
import {hubGuides} from '../src/lib/hubs.mjs';
const read=n=>JSON.parse(fs.readFileSync(new URL('../src/data/'+n+'.json',import.meta.url),'utf8'));
const canonical=v=>JSON.stringify(v,(_,x)=>x&&typeof x==='object'&&!Array.isArray(x)?Object.fromEntries(Object.entries(x).sort(([a],[b])=>a<b?-1:a>b?1:0)):x);
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const original={"pyeongtaek-flower-v2-region-anjung-eup": "838d22778c00a2f61a2b02344783d6c140fb64a24563a255a995f69726d73d35", "pyeongtaek-flower-v2-region-bijeon-dong": "1e59c63de39df012984c24a263f9e39e1fead906dea7e8be8208ce6f3c824da8", "pyeongtaek-flower-v2-region-cheongbuk-eup": "b268969f9799511654db910dd9dbefa8de43de0ec268ac872146a5973e213aa5", "pyeongtaek-flower-v2-region-cheongnyong-dong": "0e27b4589f120932002b9ba7b45353c06e92d1cb175dcd14dfb0d15b699b22a4", "pyeongtaek-flower-v2-region-chilgoe-dong": "9798a60fd43e1724818a850bb6468720620a9a1b6bca7a73de93765fa2806690", "pyeongtaek-flower-v2-region-doil-dong": "36bbb97b0128d923a65cd1c7bba40863d2480d4ebd613970ae17287219ee81f2", "pyeongtaek-flower-v2-region-dokgok-dong": "daefb89a9395b2a10697866f9b2d2325c72a286387752a9b04d44bc575922f3d", "pyeongtaek-flower-v2-region-dongsak-dong": "be86d5b2427edb3140b9b088b6139727a0cca1d862c80ccd1b6038a7eef876c2", "pyeongtaek-flower-v2-region-gajae-dong": "ccd36c8cef6898c094729fab0d6cf0dbedac490ba577a1e607040ddd7a9fbe0d", "pyeongtaek-flower-v2-region-godeok-dong": "d1f139fdadc5dfae3296a66900a70f978ff6a7984aa26e1c35a73c9de893d352", "pyeongtaek-flower-v2-region-godeok-myeon": "357c7a0b5c1ac3a53944cd9644c9eb89a11cafb2b5edbdc0c685368998e3379d", "pyeongtaek-flower-v2-region-gunmun-dong": "8b6d37c16eb86bf0a521e3f13230359b1f504e063a7d697e494a4c3634f932d1", "pyeongtaek-flower-v2-region-hapjeong-dong": "25a0c23f5b8dcf9feab3cec792df9022ae14547329de75ab77e9e841d0c67007", "pyeongtaek-flower-v2-region-hyeondeok-myeon": "e9e066e0e0d0fc584b967b3194eb41bfe0b97b2083e7ee285c57b67edccb20ae", "pyeongtaek-flower-v2-region-ichung-dong": "684a2a6ee4f13d1f7f3690941d7eae97e22b9e3ff7cf024948bc0b849eeac2e6", "pyeongtaek-flower-v2-region-jangan-dong": "0ecaab23634045a18e69e101dacdb8d12f0cacd2d48c8a8efb4ec70335c9f39a", "pyeongtaek-flower-v2-region-jangdang-dong": "f567a8c4e00d663d7bec427d0fbc48aad37ca3328097e5b765e7b39e2b8eee43", "pyeongtaek-flower-v2-region-jije-dong": "10d622e567016eb18e1df6da36e7a9bbe6ece4eb3a02f852d8b72bbcfb4b55f9", "pyeongtaek-flower-v2-region-jinwi-myeon": "7ca31207449d705bdac2a836674dc59d0fa464e289567a350edff1d94cdb7c92", "pyeongtaek-flower-v2-region-jisan-dong": "fc1019aeb1ec0a2170dfd88402c9ec9efd3e18cf2f6cdba34f9ac54223b7d15c", "pyeongtaek-flower-v2-region-jukbaek-dong": "d8c17e7c84617baee4eb120ddbd2b5676df35fb8bab44c44d527ffbcc46bff02", "pyeongtaek-flower-v2-region-mogok-dong": "775247c8c122e975ff0d98002ee679af138b704fcf710a42e0efc8ba49f51caf", "pyeongtaek-flower-v2-region-oseong-myeon": "2f898d9bb5903423500252ff747aa1ec185d0f3ad0ddb7be2f3ac0f6cb34722c", "pyeongtaek-flower-v2-region-paengseong-eup": "7d5ae4a7c487adeed12d959318fa0809fba165d8b9712e880bedde2c444e97bd", "pyeongtaek-flower-v2-region-poseung-eup": "339446e4621c5358ce8484671eccc4a102c4b8dd932e3b3bbc836d832ad2562a", "pyeongtaek-flower-v2-region-pyeongtaek-dong": "31ce29ae33e38f87b7a87e7f222c8ead337d2c751ee68be0af37daf29392f9d9", "pyeongtaek-flower-v2-region-segyo-dong": "9088b1c040929dbf445ae05ddab7186aad311984277c233e20b08973d2cc52bb", "pyeongtaek-flower-v2-region-seojeong-dong": "3585a6e2040d555a0274ef8d7a1e0fa17e68c36a515c432b39c3425d4b435616", "pyeongtaek-flower-v2-region-seotan-myeon": "4701380b73b5707acf23fd7baaa184725bf29b77dabe27fa9fc4e596a0ee64f1", "pyeongtaek-flower-v2-region-sindae-dong": "11860ce547e852679557e03bb3c001525b0e894656455b971d62532369c9ea82", "pyeongtaek-flower-v2-region-sinjang-dong": "72a7970d2bb98947bf2a9bad6377daa49ff1cdf4698c4a1f0895130134285a92", "pyeongtaek-flower-v2-region-sosa-dong": "e845e2c756f93a46222b5d9e28ca0923c44cc58ce414de326a41eedc0b26562c", "pyeongtaek-flower-v2-region-tongbok-dong": "fcc2b33c3d8cf2078f83fc633d251a6c2be5c0c64970aa0a1fcdfc882b568dba", "pyeongtaek-flower-v2-region-yongi-dong": "dcf6a3954d5e6b14c669423a259aed8850f20d8351d2151575c63dd7a22224d3", "pyeongtaek-flower-v2-region-yucheon-dong": "03a78899b6d1e13e131aa1e5a0e64d7784da4b53eb9ca8b2183c5a34881ae951"};
test('35 historical original complete objects remain in evidence and route order survives revision',()=>{
 const p=JSON.parse(fs.readFileSync(new URL('./fixtures/original-pages-before-copy.json',import.meta.url),'utf8'));assert.deepEqual(p.slice(0,35).map(x=>x.pageKey),Object.keys(original));assert.deepEqual(read('pages').slice(0,35).map(x=>x.pageKey),Object.keys(original));for(const a of p.slice(0,35))assert.equal(sha(canonical(a)),original[a.pageKey]);
});
test('initial 37 scope and two held pages remain separate from additive N1',()=>{
 const m=read('publish-manifest');assert.equal(m.directRelease.plannedOriginalCount,37);assert.equal(m.directRelease.publishedCount,35);assert.equal(m.directRelease.deferredPageKeys.length,2);assert.equal(m.additiveBatches[0].plannedOriginalCount,1);assert.equal(m.additiveBatches[0].previousPublishedCount,35);
 const p=read('pages');assert.equal(p.length,36);assert.equal(p.filter(x=>x.pageType==='regional-service').length,35);assert.ok(!p.some(x=>['chilwon-dong','wolgok-dong'].includes(x.slug)));
});
test('new exact snapshot and four card promise bind across collections',()=>{
 const p=read('pages').at(-1);assert.equal(p.url,'/event/pyeongtaek-art-center-performance-wreath/');assert.equal(p.title,p.h1);assert.equal(p.productCardLimit,4);assert.deepEqual(selectProducts(p,read('products'),4).map(x=>x.key),p.productCardKeys);assert.equal(p.productCardKeys.length,4);
 const omit=new Set(['approvalVerified','status','file','order','sourceMode','snapshotId','snapshotHash']);const h=sha(canonical(Object.fromEntries(Object.entries(p).filter(([k])=>!omit.has(k)))));assert.equal(p.snapshotHash,h);
 for(const n of ['page-map','architecture','publish-manifest'])assert.equal(read(n).pages.at(-1).snapshotHash,h);
 const row=read('publish-manifest').directRelease.contentHashes.at(-1);assert.equal(row.publicSourceSha256,h);assert.equal(row.bodySha256,sha(p.contentMarkdown));
});
test('event hub matches only active congrats and remains noindex at one article',()=>{
 assert.deepEqual(hubGuides.event.families,['congrats']);assert.doesNotMatch(JSON.stringify(hubGuides.event),/꽃다발|꽃바구니/);const h=read('architecture').hubs.find(x=>x.category==='event');assert.equal(h.children,1);assert.equal(h.indexable,false);
});

